export type Cell = [number, number];

export function nextGeneration(cells: Cell[]): Cell[] {
  const living = new Set(cells.map(([x, y]) => `${x},${y}`));

  const countLiveNeighbours = (x: number, y: number): number => {
    let count = 0;
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        if (dx === 0 && dy === 0) continue;
        if (living.has(`${x + dx},${y + dy}`)) count++;
      }
    }
    return count;
  };

  const candidates = new Map<string, Cell>();
  for (const [x, y] of cells) {
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        candidates.set(`${x + dx},${y + dy}`, [x + dx, y + dy]);
      }
    }
  }

  const survivors: Cell[] = [];
  for (const [key, [x, y]] of candidates) {
    const neighbours = countLiveNeighbours(x, y);
    const isAlive = living.has(key);
    if (neighbours === 3 || (isAlive && neighbours === 2)) {
      survivors.push([x, y]);
    }
  }
  return survivors;
}

