export type Cell = [number, number];

const NEIGHBOURS_TO_BE_BORN = 3;
const NEIGHBOURS_TO_SURVIVE = 2;

const keyOf = ([x, y]: Cell): string => `${x},${y}`;

const neighboursOf = ([x, y]: Cell): Cell[] => {
  const neighbours: Cell[] = [];
  for (let dx = -1; dx <= 1; dx++) {
    for (let dy = -1; dy <= 1; dy++) {
      if (dx !== 0 || dy !== 0) neighbours.push([x + dx, y + dy]);
    }
  }
  return neighbours;
};

export function nextGeneration(cells: Cell[]): Cell[] {
  const living = new Set(cells.map(keyOf));
  const isLiving = (cell: Cell): boolean => living.has(keyOf(cell));

  const candidates = new Map<string, Cell>();
  for (const cell of cells) {
    for (const candidate of [cell, ...neighboursOf(cell)]) {
      candidates.set(keyOf(candidate), candidate);
    }
  }

  const nextCells: Cell[] = [];
  for (const cell of candidates.values()) {
    const liveNeighbours = neighboursOf(cell).filter(isLiving).length;
    const isBorn = liveNeighbours === NEIGHBOURS_TO_BE_BORN;
    const survives = isLiving(cell) && liveNeighbours === NEIGHBOURS_TO_SURVIVE;
    if (isBorn || survives) {
      nextCells.push(cell);
    }
  }
  return nextCells;
}

